examples.template:
MonarchSectionCard(
    title = {{title}},
    description = {{description}},
    meta = {{meta}},
    icon = { MonarchIcon(SampleIcons.Clock, contentDescription = null) },
    actions = {
        MonarchButton(
            text = {{addLabel}},
            onClick = {},
            size = MonarchButtonSize.Sm,
            leadingIcon = { MonarchIcon(SampleIcons.Plus, contentDescription = null) },
        )
        MonarchLink(
            text = {{linkLabel}},
            onClick = {},
            variant = MonarchLinkVariant.Standalone,
            trailingIcon = { MonarchIcon(SampleIcons.ChevronRight, contentDescription = null) },
        )
    },
    footer = { MonarchText(text = {{footer}}, style = MonarchTextStyle.Caption) },
) {
    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        MonarchText(text = {{tasks.0}})
        MonarchText(text = {{tasks.1}})
        MonarchText(text = {{tasks.2}})
    }
}

examples.code:
MonarchSectionCard(
    title = "Open tasks",
