    actions = {
        MonarchButton(
            text = "Add",
            onClick = {},
            size = MonarchButtonSize.Sm,
            leadingIcon = { MonarchIcon(SampleIcons.Plus, contentDescription = null) },
        )
        MonarchLink(
            text = "View all tasks",
            onClick = {},
            variant = MonarchLinkVariant.Standalone,
            trailingIcon = { MonarchIcon(SampleIcons.ChevronRight, contentDescription = null) },
        )
    },
    footer = { MonarchText(text = "Updated just now", style = MonarchTextStyle.Caption) },
) {
    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        MonarchText(text = "Draft the launch brief")
